<template><div class="ui-transfer"><section><header><strong>{{sourceTitle}}</strong><span>{{available.length}}</span></header><UiSearchInput v-model="leftQuery" density="dense" placeholder="搜索可选项"/><div class="ui-transfer__list"><button v-for="item in filteredAvailable" :key="String(item.value)" type="button" @click="moveIn(item.value)"><span>{{item.label}}</span><Icon name="chevronRight" size="sm"/></button></div></section><section><header><strong>{{targetTitle}}</strong><span>{{selected.length}}</span></header><UiSearchInput v-model="rightQuery" density="dense" placeholder="搜索已选项"/><div class="ui-transfer__list"><button v-for="item in filteredSelected" :key="String(item.value)" type="button" @click="moveOut(item.value)"><Icon name="chevronLeft" size="sm"/><span>{{item.label}}</span></button></div></section></div></template>
<script setup lang="ts">import{computed,ref}from'vue';import Icon from '@/components/icons/Icon.vue';import UiSearchInput from './UiSearchInput.vue';import type{UiChoiceOption}from'./types';const props=withDefaults(defineProps<{modelValue:(string|number)[];options:UiChoiceOption[];sourceTitle?:string;targetTitle?:string}>(),{sourceTitle:'可选择',targetTitle:'已选择'});const emit=defineEmits<{'update:modelValue':[(string|number)[]]}>();const leftQuery=ref(''),rightQuery=ref('');const available=computed(()=>props.options.filter(item=>!props.modelValue.includes(item.value)));const selected=computed(()=>props.options.filter(item=>props.modelValue.includes(item.value)));const filter=(items:UiChoiceOption[],query:string)=>items.filter(item=>item.label.toLowerCase().includes(query.toLowerCase()));const filteredAvailable=computed(()=>filter(available.value,leftQuery.value));const filteredSelected=computed(()=>filter(selected.value,rightQuery.value));function moveIn(value:string|number){emit('update:modelValue',[...props.modelValue,value])}function moveOut(value:string|number){emit('update:modelValue',props.modelValue.filter(item=>item!==value))}</script>
<style scoped>.ui-transfer{display:grid;grid-template-columns:1fr 1fr;gap:8px}.ui-transfer>section{min-width:0;padding:8px;border:1px solid var(--ui-border);border-radius:var(--ui-radius);background:var(--ui-surface)}.ui-transfer header{display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;font-size:12px}.ui-transfer header span{color:var(--ui-text-soft);font-size:10px}.ui-transfer__list{height:190px;margin-top:6px;overflow:auto}.ui-transfer__list button{display:flex;width:100%;min-height:30px;align-items:center;justify-content:space-between;gap:6px;padding:4px 6px;border:0;border-radius:4px;color:var(--ui-text);background:transparent;font-size:12px;text-align:left}.ui-transfer__list button:hover{background:var(--ui-surface-muted)}@media(max-width:560px){.ui-transfer{grid-template-columns:1fr}.ui-transfer__list{height:130px}}</style>
